#include "PackageHost.h"
namespace midnightShow {
namespace {
var packageObject(){return var(new DynamicObject());}
var packageCopy(const var& v){return JSON::parse(JSON::toString(v));}
bool relativeAsset(const String& path){if(path.isEmpty()||File::isAbsolutePath(path)||path.containsChar(':')||path.containsChar('\\'))return false;for(auto part:StringArray::fromTokens(path,"/",""))if(part==".."||part=="."||part.isEmpty())return false;return true;}
MemoryBlock assetBytes(const var& bundle,const String& path){MemoryBlock block;require(block.fromBase64Encoding(bundle["files"][Identifier(path)].toString()),"Invalid embedded package asset");return block;}
String contentHash(const var& manifest,const var& files){auto data=packageObject();data.getDynamicObject()->setProperty("manifest",manifest);data.getDynamicObject()->setProperty("files",files);auto text=JSON::toString(data,false);return juce::SHA256(text.toRawUTF8(),text.getNumBytesAsUTF8()).toHexString();}
}
String packageHash(const var& b){return contentHash(b["manifest"],b["files"]);}
String packageSource(const var& b){auto bytes=assetBytes(b,b["manifest"]["entry"].toString());return String::fromUTF8(static_cast<const char*>(bytes.getData()),int(bytes.getSize()));}
void validatePackage(const var& b){const auto m=b["manifest"];require(m.isObject()&&b["files"].isObject(),"Package manifest/files missing");require(int(m["apiVersion"])==1&&m["runtimeProfile"].toString()=="juce-small-js-v1","Unsupported package API/runtime profile");require(m["id"].toString().isNotEmpty()&&m["version"].toString().isNotEmpty(),"Package ID/version required");auto life=m["lifetime"].toString();require(life=="finite"||life=="persistent","Package lifetime must be finite or persistent");auto entry=m["entry"].toString();require(relativeAsset(entry)&&b["files"].hasProperty(Identifier(entry)),"Missing or invalid relative entry");require(assetBytes(b,entry).getSize()<=256*1024,"Small-program entry exceeds 256 KiB");require(m["dependencies"].isVoid()||m["dependencies"].size()==0,"This runtime profile has no external library dependencies");
 std::set<String> aliases;StringArray allowed{"status","hostTimer","assets"};for(auto key:{"inputs","commands"})if(auto* values=m[key].getArray())for(auto value:*values){auto alias=value["alias"].toString();require(alias.isNotEmpty()&&aliases.insert(alias).second,"Package aliases must be nonempty and unique");allowed.add(String(key)=="inputs"?"read:"+alias:"write:"+alias);if(String(key)=="commands"){auto op=value["operation"].toString();require(op=="start"||op=="setValue","Unsupported declared command operation");}}
 if(auto* caps=m["capabilities"].getArray())for(auto cap:*caps)require(allowed.contains(cap.toString()),"Undeclared/unsupported package capability: "+cap.toString().toStdString());else throw std::runtime_error("Package capabilities must be declared");
 size_t total=0;for(auto pair:b["files"].getDynamicObject()->getProperties()){auto path=pair.name.toString();require(relativeAsset(path),"Asset path escapes package");auto data=assetBytes(b,path);total+=data.getSize();require(data.getSize()<=4*1024*1024&&total<=16*1024*1024,"Small package asset budget exceeded");}
 if(auto* assets=m["assets"].getArray())for(auto asset:*assets)require(b["files"].hasProperty(Identifier(asset.toString())),"Declared asset missing");require(b["sha256"].toString()==packageHash(b),"Package content hash mismatch");
}
var importPackage(const File& folder){auto manifest=JSON::parse(folder.getChildFile("manifest.json"));require(manifest.isObject(),"Select a folder with manifest.json");StringArray paths;paths.add(manifest["entry"].toString());if(auto* assets=manifest["assets"].getArray())for(auto p:*assets)paths.addIfNotAlreadyThere(p.toString());auto files=packageObject();for(auto path:paths){require(relativeAsset(path),"Package asset must be a relative child path");auto file=folder.getChildFile(path);require(file.isAChildOf(folder)&&file.existsAsFile(),"Package asset missing");MemoryBlock bytes;require(file.loadFileAsData(bytes),"Cannot read package asset");files.getDynamicObject()->setProperty(Identifier(path),bytes.toBase64Encoding());}auto bundle=packageObject();bundle.getDynamicObject()->setProperty("manifest",manifest);bundle.getDynamicObject()->setProperty("files",files);bundle.getDynamicObject()->setProperty("sha256",contentHash(manifest,files));validatePackage(bundle);return bundle;}
var packageParameters(const var& b,const var& authored){auto out=packageObject();std::set<String> ids;if(auto* fields=b["manifest"]["parameters"].getArray())for(auto field:*fields){auto id=field["id"].toString(),type=field["type"].toString();require(id.isNotEmpty()&&ids.insert(id).second,"Invalid parameter ID");auto value=authored.hasProperty(Identifier(id))?authored[Identifier(id)]:field["default"];if(type=="number"){require(value.isDouble()||value.isInt()||value.isInt64(),"Numeric parameter required");finite(double(value));if(field.hasProperty("min"))require(double(value)>=double(field["min"]),"Parameter below declared minimum");if(field.hasProperty("max"))require(double(value)<=double(field["max"]),"Parameter above declared maximum");}else if(type=="bool")require(value.isBool(),"Boolean parameter required");else if(type=="string")require(value.isString(),"String parameter required");else throw std::runtime_error("Unsupported parameter type");out.getDynamicObject()->setProperty(Identifier(id),value);}if(auto* obj=authored.getDynamicObject())for(auto pair:obj->getProperties())require(ids.count(pair.name.toString())!=0,"Unknown package parameter");return out;}
struct PackageSession::Impl {
 struct Task {enum Type{Frame,Result}type=Frame;double live=0,scene=0;bool playing=false;var inputs;uint64_t request=0;bool accepted=false;String outcome;};
 struct TimerItem {String id,scope;double due=0;};
 PackageSession& owner;std::mutex mutex;std::condition_variable wake;std::deque<Task> queue;std::vector<Message> output;std::thread worker;
 std::atomic<bool> admission{true},stopping{false},done{false};bool completeRequested=false;uint64_t sequence=0;double live=0,scene=0;bool sceneRunning=true;std::map<String,var> lastInputs;std::map<String,TimerItem> timers;StringArray capabilities;var context;
 explicit Impl(PackageSession& owner):owner(owner){if(auto* caps=owner.bundle["manifest"]["capabilities"].getArray())for(auto cap:*caps)capabilities.add(cap.toString());context=packageObject();context.getDynamicObject()->setProperty("params",packageCopy(owner.params));context.getDynamicObject()->setProperty("packageHash",owner.hash);}
 ~Impl(){close();if(worker.joinable())worker.join();}
 void close(){admission=false;stopping=true;{std::lock_guard<std::mutex> lock(mutex);queue.clear();}wake.notify_all();}
 void push(Task task){if(!admission)return;std::lock_guard<std::mutex> lock(mutex);if(queue.size()>=128){admission=false;stopping=true;output.push_back({Message::Error,0,"queue",String("Package callback queue limit exceeded"),false});}else queue.push_back(std::move(task));wake.notify_one();}
 void emit(Message m){std::lock_guard<std::mutex> lock(mutex);if(output.size()>=128){admission=false;stopping=true;output.clear();output.push_back({Message::Error,0,"queue",String("Package output queue limit exceeded"),false});}else output.push_back(std::move(m));}
 void error(const String& callback,const String& error){admission=false;stopping=true;emit({Message::Error,0,callback,error,false});}
 struct Host:DynamicObject {
  Impl& p;explicit Host(Impl& p):p(p){setMethod("request",request);setMethod("complete",complete);setMethod("status",status);setMethod("timer",timer);setMethod("fail",fail);setMethod("assetText",assetText);}
  static Impl& self(const var::NativeFunctionArgs& a){return static_cast<Host*>(a.thisObject.getDynamicObject())->p;}
  static var fail(const var::NativeFunctionArgs& a){auto& p=self(a);p.error("host.fail",a.numArguments?a.arguments[0].toString():"Package declared failure");return false;}
  static var assetText(const var::NativeFunctionArgs& a){auto& p=self(a);require(p.capabilities.contains("assets")&&a.numArguments==1,"assets capability and relative asset name required");auto name=a.arguments[0].toString();bool declared=false;if(auto* assets=p.owner.bundle["manifest"]["assets"].getArray())for(auto asset:*assets)declared|=asset.toString()==name;require(declared,"Asset was not declared in manifest");auto bytes=assetBytes(p.owner.bundle,name);return String::fromUTF8(static_cast<const char*>(bytes.getData()),int(bytes.getSize()));}
  static var request(const var::NativeFunctionArgs& a){auto& p=self(a);if(!p.admission||p.completeRequested)return -1;require(a.numArguments>=2,"host.request(alias,value[,restart])");auto alias=a.arguments[0].toString();require(p.capabilities.contains("write:"+alias),"Package lacks declared write capability");auto value=a.arguments[1];require(value.isInt()||value.isInt64()||value.isDouble()||value.isBool()||(value.isString()&&value.toString().length()<=4096),"Host requests accept a bounded primitive value");auto id=++p.sequence;p.emit({Message::Request,id,alias,value,a.numArguments>2&&bool(a.arguments[2])});return int64(id);}
  static var complete(const var::NativeFunctionArgs& a){auto& p=self(a);if(!p.admission||p.completeRequested)return false;require(p.owner.bundle["manifest"]["lifetime"].toString()=="finite","Persistent packages do not declare finite completion");p.completeRequested=true;p.emit({Message::Complete});return true;}
  static var status(const var::NativeFunctionArgs& a){auto& p=self(a);if(!p.admission||p.completeRequested)return false;require(p.capabilities.contains("status")&&a.numArguments>0,"Status capability required");p.emit({Message::Status,0,{},a.arguments[0].toString().substring(0,500),false});return true;}
  static var timer(const var::NativeFunctionArgs& a){auto& p=self(a);if(!p.admission||p.completeRequested)return false;require(p.capabilities.contains("hostTimer")&&a.numArguments==3,"host.timer(id,delay,live|scene) requires hostTimer capability");auto id=a.arguments[0].toString(),scope=a.arguments[2].toString();double delay=double(a.arguments[1]);finite(delay);require(delay>=.01&&delay<=86400,"Timer delay must be .01..86400 seconds");require(scope=="live"||scope=="scene","Timer clock must be explicit: live or scene");require(p.timers.size()<64||p.timers.count(id),"Maximum 64 outstanding timers");p.timers[id]={id,scope,(scope=="live"?p.live:p.scene)+delay};return true;}
 };
 bool call(JavascriptEngine& engine,const String& name,const Array<var>& args){if(!engine.getRootObjectFunctionNames().contains(name))return true;juce::Result result=juce::Result::ok();try{engine.callFunction(Identifier(name),var::NativeFunctionArgs(var(),args.getRawDataPointer(),args.size()),&result);if(result.failed()){error(name,result.getErrorMessage());return false;}}catch(const std::exception& e){error(name,e.what());return false;}return true;}
 void run(){JavascriptEngine engine;engine.maximumExecutionTime=RelativeTime::milliseconds(10);engine.registerNativeObject("host",new Host(*this));try{auto result=engine.execute(packageSource(owner.bundle));if(result.failed())error("entry",result.getErrorMessage());else if(!engine.getRootObjectFunctionNames().contains("onStart"))error("entry","onStart(context) is required");else call(engine,"onStart",{context});}catch(const std::exception& e){error("entry",e.what());}
  while(!stopping){Task task;{std::unique_lock<std::mutex> lock(mutex);wake.wait(lock,[&]{return stopping||!queue.empty();});if(stopping)break;task=std::move(queue.front());queue.pop_front();}
   if(task.type==Task::Result){auto result=packageObject();result.getDynamicObject()->setProperty("requestId",int64(task.request));result.getDynamicObject()->setProperty("accepted",task.accepted);result.getDynamicObject()->setProperty("outcome",task.outcome);call(engine,"onRequestResult",{context,result});continue;}
   live=task.live;scene=task.scene;sceneRunning=task.playing;context.getDynamicObject()->setProperty("liveTime",live);context.getDynamicObject()->setProperty("sceneTime",scene);context.getDynamicObject()->setProperty("scenePlaying",sceneRunning);
   if(auto* inputs=task.inputs.getDynamicObject())for(auto pair:inputs->getProperties()){auto alias=pair.name.toString();if(!lastInputs.count(alias)||lastInputs[alias]!=pair.value){lastInputs[alias]=pair.value;call(engine,"onInput",{context,alias,pair.value,int64(++sequence)});if(stopping)break;}}
   std::vector<String> due;for(auto pair:timers)if((pair.second.scope=="live"||sceneRunning)&&(pair.second.scope=="live"?live:scene)>=pair.second.due)due.push_back(pair.first);for(auto id:due){timers.erase(id);call(engine,"onTimer",{context,id});if(stopping)break;}
   if(!stopping&&(sceneRunning||owner.bundle["manifest"]["tickScope"].toString()=="live"))call(engine,"onTick",{context});
  }
  admission=false;timers.clear();call(engine,"onStop",{context,String("Host closed admission; declarative cleanup is independent of this hook")});done=true;
 }
};
PackageSession::PackageSession(Coordinator& c,const std::shared_ptr<Run>& r):generation(r->generation),bundle(packageCopy(r->cue->package)){validatePackage(bundle);params=packageParameters(bundle,r->cue->parameters);hash=packageHash(bundle);auto manifest=bundle["manifest"];auto aliases=r->cue->aliases;
 if(auto* commands=manifest["commands"].getArray())for(auto command:*commands){Binding b;b.alias=command["alias"].toString();auto ref=aliases[Identifier(b.alias)];auto kind=ref["kind"].toString();if(kind=="cue"){auto event=r->cue->packageCommands.find(b.alias);require(event!=r->cue->packageCommands.end(),"Command alias was missing at run acceptance; Restart after fixing the target");b.motor=true;b.event=event->second;b.required=command.getProperty("required",b.event.kind==Kind::Move);b.event.id="show/"+r->id+"/package/"+b.alias.toStdString();if(command["operation"].toString()=="setValue"){require(b.event.kind==Kind::Move,"setValue motor alias must be a Move");b.event.mappingStream=true;b.event.curve={};b.event.curveData.clear();b.required=false;}}
 else if(kind=="parameter"){auto target=r->cue->packageTargets.find(b.alias);if(target!=r->cue->packageTargets.end())b.parameter=target->second;require(b.parameter!=nullptr&&!b.parameter->isControllableFeedbackOnly,"Command parameter alias missing or read-only");require(command["operation"].toString()=="setValue","Parameter aliases use setValue");}
 else throw std::runtime_error("Missing/unsupported output alias binding");bindings[b.alias]=b;}
 if(auto* declared=manifest["inputs"].getArray())for(auto input:*declared){Input i;i.alias=input["alias"].toString();bool allowed=false;if(auto* caps=manifest["capabilities"].getArray())for(auto cap:*caps)allowed|=cap.toString()=="read:"+i.alias;require(allowed,"Declared input requires its read capability");i.live=input["scope"].toString()=="live";auto ref=aliases[Identifier(i.alias)];if(ref["kind"].toString()=="motor"){i.motor=ref["id"].toString().toStdString();require(service()->snapshot().motors.count(i.motor)!=0,"Input motor alias missing");}else{auto target=r->cue->packageTargets.find(i.alias);if(target!=r->cue->packageTargets.end())i.parameter=target->second;require(i.parameter!=nullptr,"Input parameter alias missing");}inputs.push_back(i);}
 impl=std::make_unique<Impl>(*this);impl->live=monotonic();impl->scene=c.clock(*r,impl->live);impl->context.getDynamicObject()->setProperty("liveTime",impl->live);impl->context.getDynamicObject()->setProperty("sceneTime",impl->scene);impl->context.getDynamicObject()->setProperty("scenePlaying",c.schedulingAllowed(*r));impl->worker=std::thread([this]{impl->run();});
}
PackageSession::~PackageSession(){stop(true);}
bool PackageSession::isOpen()const{return impl&&impl->admission;}
void PackageSession::frame(double live,double scene,bool playing,const var& inputs){Impl::Task task;task.live=live;task.scene=scene;task.playing=playing;task.inputs=packageCopy(inputs);impl->push(std::move(task));}
void PackageSession::requestResult(uint64_t id,bool accepted,const String& outcome){Impl::Task task;task.type=Impl::Task::Result;task.request=id;task.accepted=accepted;task.outcome=outcome;impl->push(std::move(task));}
std::vector<PackageSession::Message> PackageSession::drain(){std::lock_guard<std::mutex> lock(impl->mutex);std::vector<Message> result;result.swap(impl->output);return result;}
void PackageSession::stop(bool cleanup){if(impl)impl->close();if(cleanup&&service())for(auto& pair:bindings)if(pair.second.handle)service()->endOwned(pair.second.handle);}
bool PackageSession::owns()const{if(isOpen())return true;if(service())for(const auto& pair:bindings)if(pair.second.handle&&service()->observe(pair.second.handle).held)return true;return false;}
void PackageSession::update(Coordinator& c,const std::shared_ptr<Run>& r,double now){
 for(auto message:drain()){
  if(message.type==Message::Error){failure=message.alias+": "+message.value.toString();failed=true;stop(true);c.finish(r,Outcome::Failed,"Package "+hash.substring(0,12)+" "+failure);c.note("Package callback error; exact declarative cleanup performed: "+failure);continue;}
  if(message.type==Message::Status){status=message.value.toString();r->detail=status;continue;}
  if(!r->admitted||r->generation!=generation||failed||logicComplete||!isOpen()){c.note("Rejected stale/closed package callback");continue;}
  if(message.type==Message::Complete){bool missing=false;for(auto& pair:bindings)missing|=pair.second.required&&!pair.second.handle;if(missing){failed=true;stop(true);c.finish(r,Outcome::Failed,"Required package child was never launched");continue;}logicComplete=true;impl->admission=false;{std::lock_guard<std::mutex> lock(impl->mutex);impl->queue.clear();}r->detail="Package logic completed; awaiting required finite children";continue;}
  auto found=bindings.find(message.alias);bool accepted=false;String reason;
  if(found==bindings.end())reason="Undeclared output alias";else {auto& b=found->second;try{
   if(b.motor){if(b.handle&&!message.restart&&!b.event.mappingStream){auto current=service()->observe(b.handle);require(!current.current||current.execution.status!=Status::Running,"Alias is busy; request explicit restart to replace it");}auto event=b.event;if(event.mappingStream){event.target=double(message.value);finite(event.target);}auto receipt=service()->tryLaunch(event);accepted=receipt.accepted;reason=receipt.reason;if(accepted){b.handle=receipt.handle;b.last=Outcome::Pending;b.request=message.request;}}
   else {require(b.parameter!=nullptr,"Output alias target was deleted");b.parameter->setValue(message.value);accepted=true;b.request=message.request;b.last=Outcome::Succeeded;}
  }catch(const std::exception& e){reason=e.what();}}
  requestResult(message.request,accepted,accepted?"Accepted":reason);c.note("Package request "+String(int64(message.request))+" "+message.alias+(accepted?" accepted":" rejected: "+reason));if(!accepted){failed=true;failure=reason;stop(true);c.finish(r,Outcome::Failed,"Package output request failed: "+reason);}
 }
 bool all=true;for(auto& pair:bindings){auto& b=pair.second;if(b.handle){auto observation=service()->observe(b.handle);auto outcome=observation.succeeded?Outcome::Succeeded:!observation.current||observation.execution.status==Status::Superseded?Outcome::Superseded:observation.execution.status==Status::Failed?Outcome::Failed:Outcome::Pending;if(outcome!=b.last){b.last=outcome;requestResult(b.request,true,outcomeName(outcome));}if(b.required){all&=outcome==Outcome::Succeeded;if(outcome==Outcome::Failed||outcome==Outcome::Superseded){failed=true;stop(true);c.finish(r,Outcome::Failed,"Required package child did not succeed");}}}}
 if(logicComplete&&all&&!failed)c.finish(r,Outcome::Succeeded,"Finite package and required native children succeeded; holding remains endable");
 if(!isOpen()||now-lastFrame<.02)return;lastFrame=now;auto values=packageObject();auto snapshot=service()->snapshot();bool playing=c.schedulingAllowed(*r);for(const auto& input:inputs){if(!playing&&!input.live)continue;var value;if(!input.motor.empty()){auto i=snapshot.motors.find(input.motor);if(i==snapshot.motors.end()||i->second.at<0||now-i->second.at>.15)continue;value=i->second.position;}else if(input.parameter!=nullptr)value=input.parameter->getValue();else continue;values.getDynamicObject()->setProperty(Identifier(input.alias),value);}frame(now,c.clock(*r,now),playing,values);
}
}
